<?php echo form_open(get_uri('fiscal/invoices/cancel'),['id'=>'fiscal-cancellation-form','class'=>'general-form']); echo csrf_field(); ?>
<div class="modal-body"><input type="hidden" name="document_id" value="<?php echo(int)$document->id; ?>">
<dl><dt>Serie/Folio</dt><dd><?php echo esc($document->series.' '.$document->folio); ?></dd><dt>UUID</dt><dd><?php echo esc($stamp->uuid); ?></dd><dt>Receptor</dt><dd><?php echo esc($receiver->legal_name??''); ?></dd><dt>Total</dt><dd><?php echo to_currency($document->total); ?></dd></dl>
<div class="form-group"><label>Motivo de cancelación</label><?php echo form_dropdown('cancellation_reason',$reasons,'',"id='cancellation-reason' class='form-control' required"); ?></div>
<div class="form-group d-none" id="replacement-uuid-group"><label>UUID del CFDI sustituto</label><p class="text-muted">Indique el UUID del CFDI que sustituye a esta factura.</p><input type="text" class="form-control" name="replacement_uuid" id="replacement-uuid" maxlength="36" pattern="[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}"></div>
<div class="alert alert-warning">La cancelación fiscal conserva la factura, su XML, PDF, UUID e historial y no cancela la venta administrativa.<br><strong>Solicitar la cancelación consume 1 timbre comercial iKontrol.</strong><br>Saldo actual: <?php echo(int)$balance['available']; ?> timbres.</div><?php if((int)$balance['available']<1){?><div class="alert alert-danger">No cuenta con timbres suficientes para solicitar la cancelación.</div><?php }?></div>
<div id="cancellation-result"></div><div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cerrar</button><button type="submit" id="cancellation-submit" class="btn btn-danger" <?php echo(int)$balance['available']<1?'disabled':''; ?>>Solicitar cancelación y consumir 1 timbre</button></div><?php echo form_close(); ?>
<script>$(document).ready(function(){var reason=$('#cancellation-reason'),group=$('#replacement-uuid-group'),uuid=$('#replacement-uuid'),submit=$('#cancellation-submit');function sync(){var required=reason.val()==='01';group.toggleClass('d-none',!required);uuid.prop('required',required);if(!required)uuid.val('');}function reloadList(){var table=$('#fiscal-invoices-table');if(table.length)table.appTable({reload:true});else location.reload();}reason.on('change',sync);sync();$('#fiscal-cancellation-form').appForm({closeModalOnSuccess:true,onSuccess:function(r){appAlert.success(r.message);reloadList();},onError:function(r){if(r.status==='unknown'){submit.prop('disabled',true).text('Solicitud bloqueada');$('#cancellation-result').html('<div class="alert alert-warning">'+r.message+' Use Consultar estatus desde el listado.</div>');}else appAlert.error(r.message);}});});</script>
